def generate_and_save():
    knowledge_file = "datasets/destinations/destinations_rich_knowledge.json"
    existing = []
    if os.path.exists(knowledge_file):
        with open(knowledge_file, "r", encoding="utf-8") as f:
            existing = json.load(f)

    # Clean existing data for updated cities
    new_data = []
    for city, pois in ALL_DESTINATIONS.items():
        for p in pois:
            p["city"] = city
            p["region"] = p.get("region", "Global")
            p["country"] = p.get("country", city)
            new_data.append(p)

    # Keep remaining cities that are not in updated list
    kept_cities = set(ALL_DESTINATIONS.keys())
    kept_data = [d for d in existing if d.get("city") not in kept_cities]

    final_dataset = new_data + kept_data
    with open(knowledge_file, "w", encoding="utf-8") as f:
        json.dump(final_dataset, f, indent=2)

    print(f"Generated comprehensive dataset with {len(final_dataset)} total POIs across all destinations!")

if __name__ == "__main__":
    generate_and_save()
